require_once '../includes/auth.php'; require_role('teacher'); require_once '../config/db.php'; $page_title='Leave Requests';
if(isset($_GET['id'],$_GET['status']) && in_array($_GET['status'],['Approved','Rejected'],true)){ $id=(int)$_GET['id'];$status=$_GET['status'];$stmt=$conn->prepare("UPDATE tbl_leave_requests SET status=? WHERE id=?");$stmt->bind_param("si",$status,$id);$stmt->execute();header('Location: leaves.php');exit;}
