require '../includes/header.php'; ?><div class="panel"><h5>Leave Requests Waiting for Approval</h5><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Student</th><th>Leave Date</th><th>Actions</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?php echo e($r['username']);?></td><td><?php echo e($r['leave_date']);?></td><td><a class="btn btn-sm btn-success me-1" href="?id=<?php echo $r['id'];?>&status=Approved">Approve</a><a class="btn btn-sm btn-danger" href="?id=<?php echo $r['id'];?>&status=Rejected">Reject</a></td></tr><?php endwhile;?></tbody></table></div></div><?php require '../includes/footer.php'; ?>
